 "content": "def transform(grid):
    """Shear foreground cells left by their distance above the bottom edge."""
    height = len(grid)
    width = len(grid[0]) if height else 0
    rows = [r for r, row in enumerate(grid) if any(value != 0 for value in row)]
    if not rows:
        return [row[:] for row in grid]
    bottom = max(rows)
    out = [[0] * width for _ in range(height)]
    for r, row in enumerate(grid):
        shift = r - bottom
        for c, value in enumerate(row):
            if value != 0:
                target_c = c + shift
                if 0 <= target_c < width:
                    out[r][target_c] = value
    return out
